//go:build ignore

// gen_catalog.go is the catalog generator. It is invoked by the
// `go:generate` directive in gen.go:
//
//	go generate ./catalog/...
//
// It reads the shipped catalog from attacks.Default and emits
// zz_generated_catalog.go as committed, byte-stable Go source. The generated
// file carries the "Code generated ... DO NOT EDIT" header per Go
// convention.
//
// Run it from the package directory. The generator imports the attacks
// package, so it lives behind a `//go:build ignore` tag to keep it out of
// the normal build.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"os"
	"strings"
	"time"

	"go.aledante.io/FlowSeer/src/edge/netpen/attacks"
	"go.aledante.io/FlowSeer/src/edge/netpen/check"
)

func main() {
	outPath := flag.String("output", "zz_generated_catalog.go", "generated Go source path")
	flag.Parse()
	entries := attacks.Default().Entries()

	var b bytes.Buffer
	writeHeader(&b)
	writeTable(&b, entries)

	src, err := format.Source(b.Bytes())
	if err != nil {
		fmt.Fprintf(os.Stderr, "format failed: %v\n--- source ---\n%s\n", err, b.String())
		os.Exit(1)
	}

	if err := os.WriteFile(*outPath, src, 0o644); err != nil {
		fmt.Fprintf(os.Stderr, "write %s: %v\n", *outPath, err)
		os.Exit(1)
	}
	fmt.Fprintf(os.Stdout, "OK: generated %s (%d entries)\n", *outPath, len(entries))
}

func writeHeader(b *bytes.Buffer) {
	b.WriteString("// Code generated by gen_catalog.go; DO NOT EDIT.\n")
	b.WriteString("//\n")
	b.WriteString("// Run `go generate ./catalog/...` to regenerate. The catalog is\n")
	b.WriteString("// the shipped set attacks.Default assembles.\n")
	b.WriteString("\n")
	b.WriteString("package catalog\n\n")
	b.WriteString("import (\n")
	b.WriteString("\t\"time\"\n\n")
	b.WriteString("\t\"go.aledante.io/FlowSeer/src/edge/netpen/check\"\n")
	b.WriteString(")\n\n")
}

func writeTable(b *bytes.Buffer, entries []check.Entry) {
	b.WriteString("// GeneratedEntries is the generated attack catalog: one row per\n")
	b.WriteString("// (behavior, mode) pair, sorted by (Name, Mode). It is the data\n")
	b.WriteString("// view of the shipped catalog and the single source for dispatch\n")
	b.WriteString("// names, help text, legs, and cost fields outside a running host.\n")
	b.WriteString("// Callers must treat this slice and its nested slices as read-only for\n")
	b.WriteString("// concurrent reads to be safe.\n")
	b.WriteString("var GeneratedEntries = []check.Entry{\n")

	for _, e := range entries {
		fmt.Fprintf(b, "\t{Name: %q, Mode: %q, Protocols: %s, Legs: %s, Impact: %s, Restore: %s, Affects: %s, Help: %q, Orchestration: %t},\n",
			e.Name, e.Mode, quoteSlice(e.Protocols),
			legsLiteral(e.Legs), impactLiteral(e.Impact), restoreLiteral(e.Restore), affectsLiteral(e.Affects), e.Help, e.Orchestration)
	}

	b.WriteString("}\n")
}

func quoteSlice(s []string) string {
	if len(s) == 0 {
		return "nil"
	}
	out := make([]string, len(s))
	for i, v := range s {
		out[i] = fmt.Sprintf("%q", v)
	}
	return "[]string{" + strings.Join(out, ", ") + "}"
}

func legsLiteral(l check.Legs) string {
	switch l {
	case check.AttackOnly:
		return "check.AttackOnly"
	case check.WatchOptional:
		return "check.WatchOptional"
	case check.WatchRequired:
		return "check.WatchRequired"
	}
	return fmt.Sprintf("%q", string(l))
}

func impactLiteral(i check.Impact) string {
	switch i {
	case check.ImpactNone:
		return "check.ImpactNone"
	case check.ImpactTemporary:
		return "check.ImpactTemporary"
	case check.ImpactPermanent:
		return "check.ImpactPermanent"
	}
	return fmt.Sprintf("%q", string(i))
}

func restoreLiteral(r check.Restore) string {
	kind := fmt.Sprintf("%q", string(r.Kind))
	switch r.Kind {
	case check.RestoreNone:
		kind = "check.RestoreNone"
	case check.RestoreDecay:
		kind = "check.RestoreDecay"
	case check.RestoreActive:
		kind = "check.RestoreActive"
	}
	if r.Bound == 0 {
		return "check.Restore{Kind: " + kind + "}"
	}
	return fmt.Sprintf("check.Restore{Kind: %s, Bound: %d * time.Second}", kind, int64(r.Bound/time.Second))
}

func affectsLiteral(a check.Affects) string {
	switch a {
	case check.AffectsNone:
		return "check.AffectsNone"
	case check.AffectsDevice:
		return "check.AffectsDevice"
	case check.AffectsClients:
		return "check.AffectsClients"
	case check.AffectsFabric:
		return "check.AffectsFabric"
	}
	return fmt.Sprintf("%q", string(a))
}
